// runs of non-decreasing stretch lengths L contribute L(L+1)/2
long long countSorted(vector<int>& a){
    long long ans = 0; int len = 1;
    for (size_t i = 1; i < a.size(); i++) {
        if (a[i] >= a[i-1]) len++; else { ans += 1LL*len*(len+1)/2; len = 1; }
    }
    ans += 1LL*len*(len+1)/2;
    return ans;
}

